export default async (ctx, client) => {
  const runs = await client.operations.listRuns({ behavior_ids: [70, 71], limit: 30 });
  const rows = (runs.items ?? runs.data ?? runs).map((r) => ({
    id: r.id, b: r.behavior_id ?? r.watcher_id, status: r.status,
    started: r.started_at ?? r.created_at, err: r.error_message?.slice(0, 120),
  }));
  const b = await client.behaviors.list?.({}) ?? null;
  return { runs: rows, behaviors: b?.items?.filter?.(x => [70,71].includes(x.id)) ?? null };
};

export default async (ctx, client) => {
  const runs = await client.operations.listRuns({ behavior_ids: [70, 71], limit: 30 });
  return { keys: Object.keys(runs), sample: JSON.stringify(runs).slice(0, 1200) };
};

export default async (ctx, client) => {
  const r = await client.operations.listRuns({ behavior_ids: [70, 71], limit: 40 });
  return r.runs.map((x) => `${x.id} b${x.behavior_id} ${x.status} ${x.created_at} ${x.error_message ? x.error_message.slice(0,80) : ''}`);
};

export default async (ctx, client) => {
  const a = await client.agents.list({});
  const list = a.agents ?? a.items ?? a;
  return list.map((x) => `${x.id} | ${x.slug ?? x.agent_id ?? '-'} | ${x.name}`);
};

