28	async function resolveEntityTypeMetadataSchema(
29	  sql: DbClient,
30	  organizationId: string,
31	  entityTypeSlug: string
32	): Promise<Record<string, unknown> | null> {
33	  const rows = await sql<{ metadata_schema: Record<string, unknown> | string | null }>`
34	    SELECT et.metadata_schema
35	    FROM entity_types et
36	    LEFT JOIN organization o ON o.id = et.organization_id
37	    WHERE et.slug = ${entityTypeSlug}
38	      AND et.deleted_at IS NULL
39	      AND (et.organization_id = ${organizationId} OR o.visibility = 'public')
40	    ORDER BY (et.organization_id = ${organizationId}) DESC, et.id ASC
41	    LIMIT 1
42	  `;
43	  const raw = rows[0]?.metadata_schema ?? null;
44	  if (raw == null) return null;
45	  const schema = typeof raw === 'string' ? safeParse(raw) : raw;
46	  if (!schema || typeof schema !== 'object' || Object.keys(schema).length === 0) {
47	    return null;
48	  }
49	  return schema as Record<string, unknown>;
50	}
