52	function safeParse(value: string): Record<string, unknown> | null {
53	  try {
54	    const parsed = JSON.parse(value);
55	    return parsed && typeof parsed === 'object' ? parsed : null;
56	  } catch {
57	    return null;
58	  }
59	}
