61	/**
62	 * Wrap a per-record metadata schema as the full extraction-output schema: an
63	 * array of those records living at `entityPath`. A dotted path
64	 * (`analysis.results.problems`) becomes nested required objects, so the LLM's
65	 * output object is validated end to end, not just the leaf array.
66	 */
67	export function wrapMetadataSchemaAtPath(
68	  metadataSchema: Record<string, unknown>,
69	  entityPath: string
70	): Record<string, unknown> {
71	  const segments = entityPath.split('.').filter((s) => s.length > 0);
72	  if (segments.length === 0) {
73	    // No path — the whole output is the array of records.
74	    return { type: 'array', items: metadataSchema };
75	  }
76	  // Build from the leaf array outward.
77	  let node: Record<string, unknown> = { type: 'array', items: metadataSchema };
78	  for (let i = segments.length - 1; i >= 0; i--) {
79	    node = {
80	      type: 'object',
81	      properties: { [segments[i]]: node },
82	      required: [segments[i]],
83	    };
84	  }
85	  return node;
86	}
