88	/**
89	 * Derive a watcher's extraction schema. Precedence:
90	 *  1. Entity-typed (`keying_config.entity_type`) → the type's `metadata_schema`
91	 *     wrapped as an array at `entity_path`.
92	 *  2. Reaction watcher → the reaction's exported `input` schema, cached on
93	 *     `watchers.reaction_input_schema` when the watcher is created or its script
94	 *     is set. This is how "the reaction owns the schema" reaches the worker:
95	 *     the device extracts against exactly what the reaction will `Value.Parse`.
96	 *  3. Otherwise null — the worker runs the free-form `{ summary }` fallback.
97	 *
98	 * Both the worker payload and complete_window validation resolve through here,
99	 * so extraction and validation can never drift. `watcherId` enables the reaction
100	 * lookup; omit it to skip step 2 (entity-typed-only callers).
101	 */
102	export async function deriveWatcherExtractionSchema(
103	  sql: DbClient,
104	  organizationId: string,
105	  keyingConfig: KeyingConfig | null | undefined,
106	  watcherId?: string | number | null
107	): Promise<Record<string, unknown> | null> {
108	  const entityType = keyingConfig?.entity_type?.trim();
109	  if (entityType && keyingConfig?.entity_path) {
110	    const metadataSchema = await resolveEntityTypeMetadataSchema(sql, organizationId, entityType);
111	    if (metadataSchema) return wrapMetadataSchemaAtPath(metadataSchema, keyingConfig.entity_path);
112	  }
113	  if (watcherId != null && watcherId !== '') {
114	    const rows = await sql<{ reaction_input_schema: Record<string, unknown> | string | null }>`
115	      SELECT reaction_input_schema FROM watchers
116	      WHERE id = ${watcherId} AND organization_id = ${organizationId}
117	      LIMIT 1
118	    `;
119	    const raw = rows[0]?.reaction_input_schema ?? null;
120	    if (raw == null) return null;
