export default async (ctx, client) => {
  const m = await client.entitySchema.get({ slug: '$member' });
  const t = m.entity_type ?? m;
  const kinds = t.event_kinds ?? null;
  return {
    registered_kinds: kinds ? Object.keys(kinds) : null,
    sample: kinds ? JSON.stringify(kinds[Object.keys(kinds)[0]]).slice(0, 400) : null,
  };
};

export default async (ctx, client) => {
  const p = await client.authProfiles.list({});
  const list = p.auth_profiles ?? p.profiles ?? p.items ?? p;
  return Array.isArray(list)
    ? list.map((x) => `${x.id ?? x.slug} | ${x.name ?? '-'} | models=${JSON.stringify(x.models ?? x.model ?? null)} | provider=${x.provider_slug ?? x.provider ?? '-'}`)
    : { keys: Object.keys(p), raw: JSON.stringify(p).slice(0, 800) };
};

export default async (ctx, client) => {
  const t = await client.entitySchema.getType({ slug: '$member' });
  const et = t.entity_type ?? t;
  const kinds = et.event_kinds ?? null;
  return {
    kinds: kinds ? Object.keys(kinds) : null,
    detail: kinds ? JSON.stringify(kinds).slice(0, 900) : JSON.stringify(et).slice(0, 500),
  };
};

