          author: { type: 'string', minLength: 1, description: 'Post author (never "unknown")' },
          snippet: { type: 'string', description: 'Excerpt of the post' },
          why: { type: 'string', minLength: 1, description: 'Why this matches taste — specific to this item' },
          priority: { type: 'string', enum: ['high', 'normal', 'low'] },
          source_event_id: { type: 'integer', description: 'Originating event id' },
          suggested_action: { type: 'string', description: 'Concrete next step' },
        },
      },
    },
  };

  await client.entitySchema.updateType({ slug: '$member', event_kinds: merged });

  const after = await client.entitySchema.getType({ slug: '$member' });
  return {
    before,
    after: Object.keys(after.entity_type.event_kinds ?? {}),
    social_signal: after.entity_type.event_kinds?.social_signal ?? null,
  };
}

