      query: "SELECT id, metadata->>'source_event_id' AS source_event_id FROM events WHERE semantic_type = 'social_signal' AND occurred_at > now() - interval '3 days' ORDER BY occurred_at DESC LIMIT 300",
      context: true,
    },
    {
      name: 'voice_profiles',
      query: "SELECT NULL::bigint AS id, v.name, v.metadata, v.updated_at FROM entities v WHERE v.entity_type='voice-profile' AND v.deleted_at IS NULL ORDER BY v.updated_at DESC LIMIT 20",
      context: true,
